python3 << 'EOFPYTHON'
import json
import subprocess
import csv
import time

# Parse package-lock.json
with open('/root/package-lock.json', 'r') as f:
    data = json.load(f)

packages_list = []

if 'packages' in data:
    for pkg_path, pkg_info in data['packages'].items():
        if pkg_path and pkg_path != '' and 'version' in pkg_info:
            parts = pkg_path.split('node_modules/')[-1].split('/')
            if len(parts) >= 1:
                pkg_name = '/'.join(parts)
                version = pkg_info['version']
                packages_list.append((pkg_name, version))

packages_set = set(packages_list)
packages_list = sorted(list(packages_set))

# Query OSV database for vulnerabilities
vulnerabilities = []

print(f"Checking {len(packages_list)} packages for vulnerabilities...")
print("This may take a while...\n")

for i, (pkg_name, version) in enumerate(packages_list):
    if i % 100 == 0:
        print(f"Progress: {i}/{len(packages_list)}")

    # Query OSV API
    try:
        curl_cmd = f'curl -s -X POST https://api.osv.dev/v1/query -H "Content-Type: application/json" -d \'{{"package": {{"ecosystem": "npm", "name": "{pkg_name}"}}, "version": "{version}"}}\' 2>/dev/null'
        result = subprocess.run(curl_cmd, shell=True, capture_output=True, text=True, timeout=5)

        if result.stdout:
            try:
                response = json.loads(result.stdout)
                if 'vulns' in response:
                    for vuln in response['vulns']:
                        vulnerabilities.append({
                            'package': pkg_name,
                            'version': version,
                            'vuln': vuln
                        })
            except json.JSONDecodeError:
                pass
    except Exception as e:
        pass

    time.sleep(0.1)  # Rate limiting

print(f"\nFound {len(vulnerabilities)} vulnerabilities")
if vulnerabilities:
    print("Sample vulnerabilities:")
    for v in vulnerabilities[:3]:
        print(json.dumps(v, indent=2))

